import React, { useState, useEffect } from 'react';
import { Card, Table, Space, Button, Input, Form, Select, DatePicker, message, Tag, Tooltip, Modal, Switch, InputNumber } from 'antd';
import { SearchOutlined, FilterOutlined, ReloadOutlined, ExportOutlined, DeleteOutlined, EditOutlined } from '@ant-design/icons';
import * as XLSX from 'xlsx';
import { API_BASE_URL } from '../../../utils/api';
import moment from 'moment';
import { SmileTwoTone, MehTwoTone, FrownTwoTone, QuestionCircleTwoTone } from '@ant-design/icons';

const { Option } = Select;
const { RangePicker } = DatePicker;

const InteractionManagement = () => {
  const [interactions, setInteractions] = useState([]);
  const [filteredInteractions, setFilteredInteractions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [salesStaff, setSalesStaff] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [projects, setProjects] = useState([]);
  const [filterVisible, setFilterVisible] = useState(false);
  const [filterForm] = Form.useForm();
  const [searchKeyword, setSearchKeyword] = useState('');
  const [selectedNotes, setSelectedNotes] = useState('');
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [editModalVisible, setEditModalVisible] = useState(false);
  const [form] = Form.useForm();
  const [currentRecord, setCurrentRecord] = useState(null);

  // 互動類型和狀態映射
  const interactionTypeMap = {
    phone_call: '通話',
    email: '電子郵件',
    meeting: '會議',
    site_visit: '參觀',
    other: '其他'
  };

  const interactionStatusMap = {
    initial_contact: { text: '初次接觸', color: 'blue' },
    following_up: { text: '跟進中', color: 'cyan' },
    negotiating: { text: '洽談中', color: 'orange' },
    contract_signed: { text: '已簽約', color: 'green' },
    payment_received: { text: '已收款', color: 'lime' },
    completed: { text: '已完成', color: 'green' },
    pending: { text: '待處理', color: 'default' },
    cancelled: { text: '已取消', color: 'red' }
  };

  // 與 CustomerManagement 一致的 Tag 樣式
  const StatusTag = ({ color, text }) => (
    <span style={{
      color,
      background: `${color}10`,
      borderColor: `${color}30`,
      padding: '2px 8px',
      fontSize: 13,
      borderRadius: 12,
      fontWeight: 500,
      border: `1px solid ${color}30`,
      display: 'inline-block'
    }}>{text}</span>
  );

  useEffect(() => {
    fetchInteractions();
    fetchSalesStaff();
    fetchCustomers();
    fetchProjects();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [interactions, searchKeyword]);

  const fetchInteractions = async () => {
    try {
      setLoading(true);
      // 管理員獲取所有互動記錄
      const response = await fetch(`${API_BASE_URL}/api/interactions?populate=*&sort=date:desc`);
      const data = await response.json();
      setInteractions(data.data || []);
      setFilteredInteractions(data.data || []);
    } catch (error) {
      console.error('Error fetching interactions:', error);
      message.error('獲取互動記錄失敗');
    } finally {
      setLoading(false);
    }
  };

  const fetchSalesStaff = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/sales-staffs`);
      const data = await response.json();
      setSalesStaff(data.data);
    } catch (error) {
      console.error('Error fetching sales staff:', error);
    }
  };

  const fetchCustomers = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/customers?populate=*`);
      const data = await response.json();
      setCustomers(data.data || []);
    } catch (error) {
      console.error('Error fetching customers:', error);
    }
  };

  const fetchProjects = async () => {
    try {
      const resp = await fetch(`${API_BASE_URL}/api/projects?pagination[pageSize]=1000`);
      const data = await resp.json();
      setProjects(data?.data || []);
    } catch (e) {
      console.error('Error fetching projects:', e);
    }
  };

  // 搜索和過濾函數
  const handleSearch = (e) => {
    setSearchKeyword(e.target.value);
  };

  const handleFilter = async () => {
    try {
      const values = await filterForm.validateFields();
      applyFilters(values);
    } catch (error) {
      console.error('Filter form validation error:', error);
    }
  };

  const handleResetFilter = () => {
    filterForm.resetFields();
    setSearchKeyword('');
    setFilteredInteractions(interactions);
    setFilterVisible(false);
  };

  const applyFilters = (formValues = null) => {
    try {
      let filtered = [...interactions];
      
      // 關鍵字搜索 - 搜尋客戶姓名、互動內容、業務人員姓名
      if (searchKeyword) {
        const keyword = searchKeyword.toLowerCase();
        filtered = filtered.filter(interaction => 
          // 搜尋客戶姓名
          (interaction.attributes.customer?.data?.attributes?.name && 
            interaction.attributes.customer.data.attributes.name.toLowerCase().includes(keyword)) ||
          // 搜尋互動內容
          (interaction.attributes.notes && interaction.attributes.notes.toLowerCase().includes(keyword)) ||
          // 搜尋業務人員姓名
          (interaction.attributes.sales_staff?.data?.attributes?.username && 
            interaction.attributes.sales_staff.data.attributes.username.toLowerCase().includes(keyword)) ||
          (interaction.attributes.sales_staff?.data?.attributes?.name && 
            interaction.attributes.sales_staff.data.attributes.name.toLowerCase().includes(keyword))
        );
      }
      
      // 表單篩選
      if (formValues) {
        // 業務人員篩選
        if (formValues.sales_staff) {
          filtered = filtered.filter(interaction => 
            interaction.attributes.sales_staff?.data?.id === formValues.sales_staff
          );
        }
        
        // 互動類型篩選
        if (formValues.type && formValues.type.length > 0) {
          filtered = filtered.filter(interaction => 
            interaction.attributes.type && formValues.type.includes(interaction.attributes.type)
          );
        }
        
        // 互動狀態篩選
        if (formValues.status && formValues.status.length > 0) {
          filtered = filtered.filter(interaction => 
            interaction.attributes.status && formValues.status.includes(interaction.attributes.status)
          );
        }
        
        // 客戶篩選
        if (formValues.customer) {
          filtered = filtered.filter(interaction => 
            interaction.attributes.customer?.data?.id === formValues.customer
          );
        }
        
        // 日期範圍篩選
        if (formValues.dateRange && formValues.dateRange[0] && formValues.dateRange[1]) {
          const startDate = new Date(formValues.dateRange[0].format('YYYY-MM-DD'));
          const endDate = new Date(formValues.dateRange[1].format('YYYY-MM-DD'));
          endDate.setHours(23, 59, 59, 999);
          
          filtered = filtered.filter(interaction => {
            if (!interaction.attributes.date) return false;
            const interactionDate = new Date(interaction.attributes.date);
            return interactionDate >= startDate && interactionDate <= endDate;
          });
        }
      }
      
      setFilteredInteractions(filtered);
      if (filtered.length !== interactions.length) {
        message.info(`共找到 ${filtered.length} 筆互動記錄`);
      }
    } catch (error) {
      console.error('Error applying filters:', error);
      message.error('過濾出錯，請重試');
      setFilteredInteractions(interactions);
    }
  };

  // 導出到Excel
  const exportToExcel = () => {
    Modal.confirm({
      title: '導出確認',
      content: `確定要導出${filteredInteractions.length}筆互動記錄嗎？`,
      okText: '確定',
      cancelText: '取消',
      onOk: () => {
        const exportData = filteredInteractions.map(interaction => ({
          '銷售人員': interaction.attributes.sales_staff?.data?.attributes?.username || '',
          '客戶': interaction.attributes.customer?.data?.attributes?.name || '',
          '互動類型': interactionTypeMap[interaction.attributes.type] || interaction.attributes.type,
          '互動日期': interaction.attributes.date,
          '互動內容': interaction.attributes.notes,
          '互動狀態': interactionStatusMap[interaction.attributes.status]?.text || interaction.attributes.status,
          '跟進日期': interaction.attributes.next_follow_up || '',
          '創建時間': new Date(interaction.attributes.createdAt).toLocaleString(),
        }));

        const ws = XLSX.utils.json_to_sheet(exportData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '互動記錄');
        XLSX.writeFile(wb, `互動記錄_${new Date().toISOString().split('T')[0]}.xlsx`);
        
        message.success(`成功導出 ${exportData.length} 筆互動記錄`);
      }
    });
  };

  const showModal = (notes) => {
    setSelectedNotes(notes);
    setIsModalVisible(true);
  };

  const handleModalClose = () => {
    setIsModalVisible(false);
  };

  // 刪除互動記錄
  const handleDelete = (record) => {
    Modal.confirm({
      title: '確認刪除',
      content: `確定要刪除與客戶「${record.attributes.customer?.data?.attributes?.name || '未知客戶'}」的互動記錄嗎？`,
      okText: '確定刪除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        try {
          const response = await fetch(`${API_BASE_URL}/api/interactions/${record.id}`, {
            method: 'DELETE',
          });

          if (!response.ok) {
            throw new Error('刪除失敗');
          }

          message.success('互動記錄已刪除');
          fetchInteractions(); // 重新載入資料
        } catch (error) {
          console.error('Error deleting interaction:', error);
          message.error('刪除互動記錄失敗');
        }
      }
    });
  };

  const getStatusColor = (status) => {
    const colors = {
      'initial_contact': 'blue',
      'following_up': 'cyan',
      'negotiating': 'orange',
      'contract_signed': 'gold',
      'payment_received': 'green',
      'completed': 'green',
      'cancelled': 'red'
    };
    return colors[status] || 'default';
  };

  const getStatusText = (status) => {
    const statusMap = {
      'initial_contact': '初次接觸',
      'following_up': '跟進中',
      'negotiating': '洽談中',
      'contract_signed': '已簽約',
      'payment_received': '已收款',
      'completed': '已完成',
      'cancelled': '已取消'
    };
    return statusMap[status] || status;
  };

  // 表格列定義
  const columns = [
    {
      title: '銷售人員',
      dataIndex: ['attributes', 'sales_staff', 'data', 'attributes', 'username'],
      key: 'sales_staff',
      render: (text) => text || '未知'
    },
    {
      title: '客戶',
      dataIndex: ['attributes', 'customer', 'data', 'attributes', 'name'],
      key: 'customer',
      render: (_, record) => record.attributes.customer?.data?.attributes?.name || '-'
    },
    {
      title: '聯絡類型',
      dataIndex: ['attributes', 'type'],
      key: 'type',
      render: (type) => interactionTypeMap[type] || type,
    },
    {
      title: '聯絡日期',
      dataIndex: ['attributes', 'date'],
      key: 'date',
      render: (date) => date || '-',
    },
    {
      title: '聯絡內容',
      dataIndex: ['attributes', 'notes'],
      key: 'notes',
      ellipsis: { showTitle: false },
      render: (notes) => {
        if (!notes) return '-';
        const displayText = notes.length > 20 ? `${notes.substring(0, 20)}...` : notes;
        return (
          <Tooltip title={notes.length > 20 ? notes : ''}>
            <Button type="link" onClick={() => showModal(notes)} style={{ padding: 0, height: 'auto', whiteSpace: 'normal', textAlign: 'left' }}>
              {displayText}
            </Button>
          </Tooltip>
        );
      }
    },
    {
      title: '狀態',
      dataIndex: ['attributes', 'status'],
      key: 'status',
      render: (status) => (<Tag color={getStatusColor(status)}>{getStatusText(status)}</Tag>),
    },
    {
      title: '聯絡結果',
      dataIndex: ['attributes', 'outcome'],
      key: 'outcome',
      render: (outcome) => {
        const map = {
          positive: { icon: <SmileTwoTone twoToneColor="#52c41a" />, text: '正向' },
          neutral: { icon: <MehTwoTone twoToneColor="#faad14" />, text: '中性' },
          negative: { icon: <FrownTwoTone twoToneColor="#ff4d4f" />, text: '負向' },
        };
        const item = map[outcome] || { icon: <QuestionCircleTwoTone twoToneColor="#8c8c8c" />, text: '-' };
        return (
          <Tooltip title={item.text}>
            <span>{item.icon}</span>
          </Tooltip>
        );
      }
    },
    { title: '相關建案', dataIndex: ['attributes', 'project', 'data', 'attributes', 'name'], key: 'project', render: (v) => v || '-' },
    { title: '是否成交', dataIndex: ['attributes', 'is_deal'], key: 'is_deal', render: (v) => v ? '是' : '否' },
    { title: '成交金額', dataIndex: ['attributes', 'deal_amount'], key: 'deal_amount', render: (v) => v || '-' },
    { title: '入帳日期', dataIndex: ['attributes', 'payment_date'], key: 'payment_date', render: (v) => v || '-' },
    {
      title: '操作', key: 'action', width: 140, fixed: 'right',
      render: (_, record) => (
        <Space>
          <Tooltip title="編輯">
            <Button type="text" onClick={() => openEdit(record)} size="small" icon={<EditOutlined />} />
          </Tooltip>
          <Tooltip title="刪除">
            <Button type="text" danger icon={<DeleteOutlined />} onClick={() => handleDelete(record)} size="small" />
          </Tooltip>
        </Space>
      ),
    },
  ];

  const openEdit = (record) => {
    setCurrentRecord(record);
    form.setFieldsValue({
      customer: record.attributes.customer?.data?.id,
      sales_staff: record.attributes.sales_staff?.data?.id,
      type: record.attributes.type,
      date: record.attributes.date,
      notes: record.attributes.notes,
      status: record.attributes.status,
      outcome: record.attributes.outcome || null,
      project: record.attributes.project?.data?.id || null,
      next_follow_up: record.attributes.next_follow_up,
      is_deal: !!record.attributes.is_deal,
      deal_amount: record.attributes.is_deal ? record.attributes.deal_amount : null,
      payment_date: record.attributes.is_deal ? record.attributes.payment_date : null,
    });
    setEditModalVisible(true);
  };

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      const payload = {
        data: {
          customer: values.customer,
          sales_staff: values.sales_staff,
          type: values.type,
          notes: values.notes,
          date: values.date,
          status: values.status,
          outcome: values.outcome || null,
          project: values.project ? values.project : null,
          next_follow_up: values.next_follow_up || null,
          is_deal: !!values.is_deal,
          deal_amount: values.is_deal ? (values.deal_amount || 0) : null,
          payment_date: values.is_deal ? (values.payment_date || null) : null,
        }
      };
      const method = currentRecord ? 'PUT' : 'POST';
      const url = currentRecord ? `${API_BASE_URL}/api/interactions/${currentRecord.id}` : `${API_BASE_URL}/api/interactions`;
      const resp = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      if (!resp.ok) throw new Error('保存失敗');
      message.success('已保存聯絡記錄');
      setEditModalVisible(false);
      setCurrentRecord(null);
      fetchInteractions();
    } catch (e) {
      console.error('save interaction failed', e);
      message.error('保存失敗');
    }
  };

  return (
    <Card
      title="聯絡記錄管理"
      extra={
        <Space>
          <Input
            placeholder="搜索客戶姓名、聯絡內容或業務人員"
            value={searchKeyword}
            onChange={handleSearch}
            prefix={<SearchOutlined />}
            style={{ width: 250 }}
          />
          <Button icon={<FilterOutlined />} onClick={() => setFilterVisible(!filterVisible)}>篩選</Button>
          <Button icon={<ReloadOutlined />} onClick={() => fetchInteractions()}>刷新</Button>
          <Button icon={<ExportOutlined />} onClick={exportToExcel}>導出Excel</Button>
        </Space>
      }
    >
      {filterVisible && (
        <div className="filter-panel" style={{ 
          backgroundColor: '#f8f8f8',
          borderRadius: '6px',
          padding: '16px',
          marginBottom: '16px',
          border: '1px solid #e8e8e8'
        }}>
          <Form
            form={filterForm}
            layout="horizontal"
            onFinish={handleFilter}
          >
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '16px' }}>
              <Form.Item name="sales_staff" label="銷售人員" style={{ minWidth: '200px' }}>
                <Select placeholder="選擇銷售人員" style={{ width: '200px' }}>
                  <Option value="">全部</Option>
                  {salesStaff.map(staff => (
                    <Option key={staff.id} value={staff.id}>
                      {staff.attributes.username}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
              <Form.Item name="type" label="互動類型" style={{ minWidth: '200px' }}>
                <Select mode="multiple" placeholder="選擇互動類型" style={{ width: '200px' }}>
                  {Object.entries(interactionTypeMap).map(([value, text]) => (
                    <Option key={value} value={value}>{text}</Option>
                  ))}
                </Select>
              </Form.Item>
              <Form.Item name="status" label="互動狀態" style={{ minWidth: '200px' }}>
                <Select mode="multiple" placeholder="選擇互動狀態" style={{ width: '200px' }}>
                  {Object.entries(interactionStatusMap).map(([value, { text }]) => (
                    <Option key={value} value={value}>{text}</Option>
                  ))}
                </Select>
              </Form.Item>
              <Form.Item name="customer" label="客戶" style={{ minWidth: '200px' }}>
                <Select 
                  placeholder="選擇客戶" 
                  style={{ width: '200px' }}
                  showSearch
                  filterOption={(input, option) =>
                    (option?.children ?? '').toLowerCase().includes(input.toLowerCase())
                  }
                >
                  <Option value="">全部</Option>
                  {customers.map(customer => (
                    <Option key={customer.id} value={customer.id}>
                      {customer.attributes.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
              <Form.Item name="dateRange" label="互動日期" style={{ minWidth: '300px' }}>
                <RangePicker />
              </Form.Item>
              <Form.Item style={{ marginLeft: 'auto' }}>
                <Space>
                  <Button type="primary" htmlType="submit">
                    篩選
                  </Button>
                  <Button onClick={handleResetFilter}>
                    重置
                  </Button>
                </Space>
              </Form.Item>
            </div>
          </Form>
        </div>
      )}

      {/* 搜尋說明 */}
      <div style={{ 
        marginBottom: 16, 
        padding: '8px 12px', 
        backgroundColor: '#f0f9ff', 
        border: '1px solid #bae6fd',
        borderRadius: '4px',
        fontSize: '14px',
        color: '#0369a1'
      }}>
        💡 搜尋提示：您可以搜尋「客戶姓名」、「互動內容」或「業務人員姓名」關鍵字來快速找到相關記錄
      </div>

      <Table
        columns={columns}
        dataSource={filteredInteractions}
        rowKey={record => record.id}
        loading={loading}
        scroll={{ x: 1200 }}
      />

      <Modal
        title="聯絡內容詳情"
        open={isModalVisible}
        onCancel={handleModalClose}
        footer={[<Button key="close" onClick={handleModalClose}>關閉</Button>]}
      >
        <p style={{ whiteSpace: 'pre-wrap' }}>{selectedNotes}</p>
      </Modal>

      <Modal
        title={currentRecord ? '編輯聯絡記錄' : '新增聯絡記錄'}
        open={editModalVisible}
        onOk={handleSave}
        onCancel={() => { setEditModalVisible(false); setCurrentRecord(null); }}
        okText="保存"
        cancelText="取消"
        width={720}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="customer" label="客戶" rules={[{ required: true, message: '請選擇客戶' }]}>
            <Select placeholder="選擇客戶" showSearch filterOption={(i, o)=> (o?.children ?? '').toLowerCase().includes(i.toLowerCase())}>
              {customers.map(c => (<Option key={c.id} value={c.id}>{c.attributes.name}</Option>))}
            </Select>
          </Form.Item>
          <Form.Item name="sales_staff" label="負責業務" rules={[{ required: true, message: '請選擇業務' }]}>
            <Select placeholder="選擇業務">
              {salesStaff.map(s => (<Option key={s.id} value={s.id}>{s.attributes.name || s.attributes.username}</Option>))}
            </Select>
          </Form.Item>
          <Form.Item name="type" label="聯絡類型" rules={[{ required: true, message: '請選擇聯絡類型' }]}>
            <Select placeholder="選擇聯絡類型">
              {Object.entries(interactionTypeMap).map(([v, t])=> (<Option key={v} value={v}>{t}</Option>))}
            </Select>
          </Form.Item>
          <Form.Item name="date" label="聯絡日期" rules={[{ required: true, message: '請選擇聯絡日期' }]}>
            <Input type="date" />
          </Form.Item>
          <Form.Item name="notes" label="聯絡內容" rules={[{ required: true, message: '請輸入聯絡內容' }]}>
            <Input.TextArea rows={4} />
          </Form.Item>
          <Form.Item name="status" label="聯絡狀態" rules={[{ required: true, message: '請選擇聯絡狀態' }]}>
            <Select placeholder="選擇聯絡狀態">
              {Object.entries(interactionStatusMap).map(([v, { text }])=> (<Option key={v} value={v}>{text}</Option>))}
            </Select>
          </Form.Item>
          <Form.Item name="outcome" label="聯絡結果">
            <Select placeholder="選擇聯絡結果">
              <Option value="positive">正向</Option>
              <Option value="neutral">中性</Option>
              <Option value="negative">負向</Option>
            </Select>
          </Form.Item>
          <Form.Item name="project" label="相關建案">
            <Select placeholder="選擇建案" showSearch filterOption={(i,o)=> (o?.children ?? '').toLowerCase().includes(i.toLowerCase())} allowClear>
              {projects.map(p => (<Option key={p.id} value={p.id}>{p.attributes?.name || `建案 ${p.id}`}</Option>))}
            </Select>
          </Form.Item>
          <Form.Item name="next_follow_up" label="下次跟進日期">
            <Input type="date" />
          </Form.Item>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            <Form.Item name="is_deal" label="是否成交" valuePropName="checked" initialValue={false}>
              <Switch />
            </Form.Item>
            <Form.Item shouldUpdate={(prev, curr) => prev.is_deal !== curr.is_deal}>
              {({ getFieldValue }) => getFieldValue('is_deal') ? (
                <div style={{ display: 'contents' }}>
                  <Form.Item name="deal_amount" label="成交金額" rules={[{ required: true, message: '請輸入成交金額' }]}>
                    <InputNumber style={{ width: '100%' }} min={0} step={10000} placeholder="輸入金額（元）" />
                  </Form.Item>
                  <Form.Item name="payment_date" label="入帳日期" rules={[{ required: true, message: '請選擇入帳日期' }]}>
                    <Input type="date" />
                  </Form.Item>
                </div>
              ) : null}
            </Form.Item>
          </div>
        </Form>
      </Modal>
    </Card>
  );
};

export default InteractionManagement; 